    public static string Biography(string role, int seed)
    {
        var bank = role switch { "职业选手" or "世界顶尖" => ProBios, "青训选手" => YouthBios, "普通玩家" => FanBios,
            _ => RoleBios.GetValueOrDefault(role, FanBios) };
        return bank[(int)((uint)seed % (uint)bank.Length)];
    }
    public static string PlayingStyle(int character, int seed) => Styles[character % Styles.Length][(int)((uint)seed % (uint)Styles[character % Styles.Length].Length)];
